// Des: Tests for ru-purg-clou: 90 to 80 rule, manifest first, keep latest, upgr mode
// Flo: fill the mock cloud with packs > purge at different caps > assert what is left
// I/O: mock cloud + temp db > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const purg = @import("ru-purg-clou.zig"); const sync = @import("sy-clou-sync.zig"); const cmok = @import("sy-clou-mock.zig"); const outb = @import("sy-clou-outb.zig"); const inde = @import("st-page-inde.zig"); const sqli = @import("st-stor-sqli.zig");
const allo = std.testing.allocator;
const Rigg = struct { tmpz: std.testing.TmpDir, cldz: cmok.Mock, dirz: []u8, dbzz: sqli.Dbzz, aren: std.heap.ArenaAllocator, synz: sync.Sync,
pub fn upzz(self: *Rigg) !void { self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); self.aren = std.heap.ArenaAllocator.init(allo); self.cldz = cmok.Mock.init(allo); self.synz = .{ .iozz = std.testing.io, .dbzz = &self.dbzz, .dirz = self.dirz, .conf = .{}, .store = self.cldz.store(), .sql2 = self.cldz.sql2() }; }
pub fn down(self: *Rigg) void { self.cldz.deinit(); self.aren.deinit(); self.dbzz.close(); allo.free(self.dirz); self.tmpz.cleanup(); }
pub fn pack(self: *Rigg, name: []const u8, size: usize, hexz: []const u8) !void { const body = try allo.alloc(u8, size); defer allo.free(body); @memset(body, 'x'); try self.synz.store.put(self.synz.store.ctx2, self.aren.allocator(), std.testing.io, name, body); var insz = try self.dbzz.prep("INSERT INTO pack(hexz,packk,offs,lenz) VALUES(?1,?2,0,1);"); defer insz.fini(); try insz.bindText(1, hexz); try insz.bindText(2, name); _ = try insz.step(); } };
fn five(rig3: *Rigg) !void { try rig3.pack("runs/20260101.pack", 20, "h1"); try rig3.pack("runs/20260102.pack", 20, "h2"); try rig3.pack("runs/20260103.pack", 20, "h3"); try rig3.pack("runs/20260104.pack", 20, "h4"); try rig3.pack("runs/20260105.pack", 20, "h5"); }
test "below 90% nothing happens" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try five(&rig3); const rslt = try purg.purgRunz(&rig3.synz, rig3.aren.allocator(), 100, 112); try std.testing.expectEqual(purg.Actz.none, rslt.act2); try std.testing.expectEqual(@as(usize, 5), rig3.cldz.map.count()); }
test "at 90% delete oldest packs until usage is at most 80%, manifest written first" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try five(&rig3); const rslt = try purg.purgRunz(&rig3.synz, rig3.aren.allocator(), 100, 111); try std.testing.expectEqual(purg.Actz.purged, rslt.act2); try std.testing.expectEqual(@as(u32, 1), rslt.pac4); try std.testing.expectEqual(@as(u64, 80), rslt.usa2); try std.testing.expect(rig3.cldz.map.get("runs/20260101.pack") == null); try std.testing.expect(rig3.cldz.map.get("runs/20260102.pack") != null); try std.testing.expectEqual(@as(usize, 1), rig3.cldz.sawzStmt("INTO cl_purg")); try std.testing.expectEqual(@as(usize, 1), rig3.cldz.sawzStmt("DELETE FROM cl_manif")); const again = try purg.purgRunz(&rig3.synz, rig3.aren.allocator(), 100, 111); try std.testing.expectEqual(purg.Actz.none, again.act2); }
test "a big overshoot repeats until under 80%" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try five(&rig3); const rslt = try purg.purgRunz(&rig3.synz, rig3.aren.allocator(), 100, 100); try std.testing.expectEqual(@as(u32, 1), rslt.pac4); try std.testing.expectEqual(@as(u64, 80), rslt.usa2); const tigh = try purg.purgRunz(&rig3.synz, rig3.aren.allocator(), 100, 70); try std.testing.expectEqual(purg.Actz.purged, tigh.act2); try std.testing.expect(tigh.usa2 <= 56); }
test "the latest version of a URL survives: its file is requeued before the pack goes" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try five(&rig3); try inde.pageSetz(&rig3.dbzz, "http://a/live", .{ .hexz = "h1", .etag = "", .lmod = "", .code = 200, .tier = 1, .vend = "", .fetc = 1, .next = 2 }); const rslt = try purg.purgRunz(&rig3.synz, rig3.aren.allocator(), 100, 111); try std.testing.expectEqual(@as(u32, 1), rslt.kept); try std.testing.expectEqual(@as(i64, 1), try outb.outbCont(&rig3.dbzz, 0)); try std.testing.expect(rig3.cldz.map.get("runs/20260101.pack") == null); }
test "mode upgr only reports, deletes nothing" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try five(&rig3); rig3.synz.conf.clou_poli_mode = "upgr"; const rslt = try purg.purgRunz(&rig3.synz, rig3.aren.allocator(), 100, 111); try std.testing.expectEqual(purg.Actz.upgr, rslt.act2); try std.testing.expectEqual(@as(usize, 5), rig3.cldz.map.count()); }
test "if the manifest cannot be written, nothing is deleted" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try five(&rig3); rig3.cldz.sqlo = true; try std.testing.expectError(error.CloudSql, purg.purgRunz(&rig3.synz, rig3.aren.allocator(), 100, 111)); try std.testing.expectEqual(@as(usize, 5), rig3.cldz.map.count()); }
